/// The active embedding model for this index. A fresh index intentionally
/// starts on the deterministic hash embedder (`HASH_MODEL_ID`): config-based
/// seeding was removed because adopting `[llm.embedding] model` before the
/// user has explicitly installed it produced surprise downloads. The
/// configured model takes effect only after an explicit `models install`.
pub(crate) fn active_embedding_model_id(conn: &Connection) -> anyhow::Result<String> {
    match read_index_meta(conn, ACTIVE_EMBEDDING_MODEL_META)? {
        Some(id) if !id.trim().is_empty() => Ok(id),
        _ => Ok(HASH_MODEL_ID.to_string()),
    }
}
